package io.github.diodeme.ji.ai;

import java.util.List;
import java.util.Optional;

/** Candidate model catalog. Entries do not replace runtime capability negotiation. */
public interface ModelCatalog {
    List<ProviderModel> models();

    default Optional<ProviderModel> find(String id) {
        return models().stream().filter(model -> model.id().equals(id)).findFirst();
    }

    static ModelCatalog fixed(List<ProviderModel> models) {
        List<ProviderModel> snapshot = List.copyOf(models);
        return () -> snapshot;
    }
}
